#ifndef LAB_03_H_
#define LAB_03_H_

#include <stdint.h>
#include <stdbool.h>

/**
 * @brief Executes the precision verification and delay test loop for Lab 03.
 *
 * Cyclically measures and validates a 1,000,000 us (1 s) delay generated by Timer2:
 * 1. Obtains the initial timestamp using DELAY_GetMillis().
 * 2. Waits for 1,000,000 us using DELAY_Microseconds().
 * 3. Determines elapsed time using DELAY_GetElapsedMillis().
 * 4. Validates accuracy: turns ON the GREEN LED if elapsed time is between 995 ms and 1005 ms;
 *    otherwise, turns ON the RED LED.
 * 5. Holds the LED output for 2 seconds using DELAY_Milliseconds().
 * 6. Turns OFF the LEDs and repeats the sequence.
 *
 * @return Does not return (contains an infinite loop).
 */
int LAB_03(void);

#endif /* LAB_03_H_ */
